chrome.action.onClicked.addListener((tab) => {
  if (tab.id) {
    chrome.scripting.executeScript({
      target: { tabId: tab.id },
      function: boostVolume
    });
  }
});

function boostVolume() {
  const video = document.querySelector('video');
  if (video) {
    video.volume = Math.min(video.volume * 4.2, 1);
  }
}
